import{_ as i}from"./chunks/fluxgrip_px4.DYpqjw-Z.js";import{_ as r,C as s,o as n,c as o,j as a,a as l,E as p,al as d}from"./chunks/framework.7vp1BMOE.js";const F=JSON.parse('{"title":"Electro-Permanent Magnet (EPM)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/peripherals/gripper_epm.md","filePath":"zh/peripherals/gripper_epm.md"}'),h={name:"zh/peripherals/gripper_epm.md"};function c(u,e,g,m,f,k){const t=s("Badge");return n(),o("div",null,[e[0]||(e[0]=a("h1",{id:"electro-permanent-magnet-epm",tabindex:"-1"},[l("Electro-Permanent Magnet (EPM) "),a("a",{class:"header-anchor",href:"#electro-permanent-magnet-epm","aria-label":'Permalink to "Electro-Permanent Magnet (EPM)"'},"​")],-1)),p(t,{type:"tip",text:"PX4 v1.18"}),e[1]||(e[1]=d('<p>An electro-permanent magnet (EPM) uses a short electrical pulse to switch its magnetic state, and does not consume power continuously while holding a payload.</p><p>This topic explains how to connect and configure a <a href="https://shop.zubax.com/products/zubax-epm" target="_blank" rel="noreferrer">Zubax FluxGrip FG40</a> EPM as a DroneCAN gripper. The gripper can then be operated from a <a href="./../flying/package_delivery_mission">payload delivery mission</a>, a joystick, or a MAVLink command.</p><p><img src="'+i+`" alt="FluxGrip connected to a Pixhawk flight controller"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This setup was tested with a Holybro Pixhawk 6X Pro and FluxGrip firmware <code>502e1f5</code>. See the <a href="https://fluxgrip.zubax.com/chapters/hardware/fg40.html#interface-and-power-supply" target="_blank" rel="noreferrer">FluxGrip documentation</a> for product-specific setup and operating limits.</p></div><h2 id="px4-firmware-support" tabindex="-1">PX4 Firmware Support <a class="header-anchor" href="#px4-firmware-support" aria-label="Permalink to &quot;PX4 Firmware Support&quot;">​</a></h2><p>DroneCAN EPM operation is supported from PX4 v1.18 — the first PX4 version that supports gripper command forwarding using the DroneCAN hardpoint message (<a href="https://dronecan.github.io/Specification/7._List_of_standard_data_types/#uavcanequipmenthardpoint" target="_blank" rel="noreferrer">uavcan.equipment.hardpoint</a>).</p><p>The flight controller firmware must include both of the following modules (and of course the board must support CAN):</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CONFIG_DRIVERS_UAVCAN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=y</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CONFIG_MODULES_PAYLOAD_DELIVERER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=y</span></span></code></pre></div><p>You can check or add these settings in the board&#39;s <code>default.px4board</code> file under <code>boards/&lt;vendor&gt;/&lt;board&gt;/</code>, or use the <a href="./../hardware/porting_guide_config#px4-menuconfig-setup">PX4 board configuration tool</a>.</p><p>Then <a href="./../dev_setup/building_px4">build PX4 and upload the firmware</a>. For an FMUv6X flight controller this would be done as follows (replace <code>px4_fmu-v6x_default</code> with the build target for your flight controller):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submodule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6x_default</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6x_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div><h2 id="硬件安装" tabindex="-1">硬件安装 <a class="header-anchor" href="#硬件安装" aria-label="Permalink to &quot;硬件安装&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>FluxGrip can briefly draw a high current when switching. FluxGrip can be powered from the flight controller power rail for testing purposes, provided that the rail meets its voltage and current requirements. For normal operation, use a suitable separate power supply for the EPM to reduce the load on the flight controller power rail and improve switching performance. Follow the voltage, current, and wiring requirements in the <a href="https://fluxgrip.zubax.com/chapters/hardware/fg40.html#interface-and-power-supply" target="_blank" rel="noreferrer">FluxGrip documentation</a>.</p></div><ol><li>Connect FluxGrip to the flight controller&#39;s <code>CAN1</code> port.</li><li>Connect FluxGrip to its power supply.</li><li>Check that the CAN bus is wired and terminated as described in <a href="./../can/#wiring">CAN Wiring</a>.</li><li>Power the flight controller and FluxGrip.</li></ol><p>When communication is working, the left CAN LED on FluxGrip is solid and the adjacent CAN LED blinks.</p><h2 id="px4-配置" tabindex="-1">PX4 配置 <a class="header-anchor" href="#px4-配置" aria-label="Permalink to &quot;PX4 配置&quot;">​</a></h2><p>Set the following parameters in QGroundControl, and then reboot the flight controller:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>值</th><th>描述</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a></td><td><code>Sensors Automatic Config</code> (<code>2</code>)</td><td>Enables DroneCAN and dynamic node allocation. Use <code>3</code> instead if the vehicle also uses DroneCAN ESCs.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#UAVCAN_BITRATE">UAVCAN_BITRATE</a></td><td><code>1000000</code></td><td>Sets the CAN bus bitrate to 1 Mbit/s.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#PD_GRIPPER_TYPE">PD_GRIPPER_TYPE</a></td><td><code>Binary Grab/Release</code> (<code>0</code>)</td><td>Enables the binary grab/release gripper interface used by the EPM.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You do not need to map a flight controller actuator output when controlling the EPM over DroneCAN. No DroneCAN subscription or publication parameters (<code>UAVCAN_SUB_*</code>, <code>UAVCAN_PUB_*</code>, <code>CANNODE_SUB_*</code>, or <code>CANNODE_PUB_*</code>) are required. PX4 automatically publishes the hardpoint command when DroneCAN is enabled.</p></div><h2 id="test-the-gripper" tabindex="-1">Test the Gripper <a class="header-anchor" href="#test-the-gripper" aria-label="Permalink to &quot;Test the Gripper&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Remove the propellers and secure the vehicle before testing. The payload deliverer commands the gripper to the grab state when the module starts, so the EPM will magnetize during startup.</p></div><p>Open the QGroundControl <a href="./../debug/mavlink_shell">MAVLink Shell</a>, then verify that the DroneCAN driver and payload deliverer are running:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uavcan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">payload_deliverer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>Test both gripper states:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Release the payload (magnet off)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">payload_deliverer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gripper_open</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Grab the payload (magnet on)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">payload_deliverer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gripper_close</span></span></code></pre></div><p>PX4 sends these as <code>MAV_CMD_DO_GRIPPER</code> commands for hardpoint ID <code>0</code>. The release command has action <code>0</code>, and the grab command has action <code>1</code>.</p><p>After testing, the EPM can be operated using any of the methods described in <a href="./gripper#using-a-gripper">Grippers &gt; Using a Gripper</a>.</p><h2 id="led-status" tabindex="-1">LED Status <a class="header-anchor" href="#led-status" aria-label="Permalink to &quot;LED Status&quot;">​</a></h2><p>The Magnet LED, located to the right of the CAN LEDs, indicates the EPM state:</p><table tabindex="0"><thead><tr><th>State</th><th>含义</th></tr></thead><tbody><tr><td>Detect/Unknown</td><td>Initial state after FluxGrip is powered on.</td></tr><tr><td>On</td><td>The EPM is magnetized and holding the payload.</td></tr><tr><td>Off</td><td>The EPM is demagnetized and the payload is released.</td></tr><tr><td>Fade-in</td><td>FluxGrip is switching to the magnetized state.</td></tr><tr><td>Fade-out</td><td>FluxGrip is switching to the demagnetized state.</td></tr></tbody></table><p>If the Magnet LED blinks rapidly, FluxGrip failed to magnetize. Check the power supply and wiring, and contact <a href="mailto:support@zubax.com" target="_blank" rel="noreferrer">Zubax support</a> if the problem persists.</p><h2 id="故障处理" tabindex="-1">故障处理 <a class="header-anchor" href="#故障处理" aria-label="Permalink to &quot;故障处理&quot;">​</a></h2><p>If FluxGrip does not respond:</p><ol><li>Run <code>uavcan status</code> and confirm that the DroneCAN driver is running and FluxGrip is visible on the bus.</li><li>Check that <code>UAVCAN_ENABLE</code> and <code>UAVCAN_BITRATE</code> are set as described above.</li><li>Check CAN wiring, bus termination, and the EPM power supply.</li><li>Run <code>payload_deliverer status</code> and confirm that the gripper is valid.</li><li>If <code>payload_deliverer</code> is not available, rebuild the firmware with <code>CONFIG_MODULES_PAYLOAD_DELIVERER=y</code>.</li></ol><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="https://forum.zubax.com/t/fluxgrip-integration-with-px4/2863" target="_blank" rel="noreferrer">FluxGrip: Integration with PX4</a> (Zubax Forum)</li><li><a href="https://forum.zubax.com/t/fluxgrip-quickstart-guide-v1-1/2864" target="_blank" rel="noreferrer">FluxGrip Quickstart Guide</a> (Zubax Forum)</li><li><a href="./../dronecan/">DroneCAN</a></li><li><a href="./gripper">Grippers</a></li></ul>`,36))])}const C=r(h,[["render",c]]);export{F as __pageData,C as default};
